local K="\047\252\049\091\165\057\144\123\236\019\009\014\045\137\075\069\240\047\086\110\253\243\125"
local D=""
local T={}
for i=1,64 do T[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",i)]=i-1 end
local B,C,S,P=bit32.bxor,string.char,{},0
local KL=#K
for i=1,#D,4 do
local a,b,c,d=string.byte(D,i,i+3)
local n=T[a]*262144+T[b]*4096+(T[c] or 0)*64+(T[d] or 0)
local x,y,z=n//65536,n//256%256,n%256
S[#S+1]=C(B(x,string.byte(K,P%KL+1)),B(y,string.byte(K,(P+1)%KL+1)),B(z,string.byte(K,(P+2)%KL+1)))
P=P+3
end
local src=table.concat(S):sub(1,194625)
local f,e=loadstring(src)
if not f then error(e,0) end
return f(...)
